import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        return lambda n, d: _lhs(n, d)
    except ImportError:
        try:
            from scipy.stats import qmc
            return lambda n, d: qmc.LatinHypercube(d=d).random(n=n)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self._lhs = _get_lhs()

    def _evaluate(self, x, func):
        if self.evals >= self.budget:
            return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if np.isfinite(f) and f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
        return f

    def _adaptive_levy(self, dim):
        u = self.rng.normal(0, 1, dim)
        v = self.rng.normal(0, 1, dim)
        return u / (np.abs(v) ** 0.5) * 1.5

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget:
            return self.best_f, self.best_x

        n_pop = max(15, min(45, self.budget // 4))
        pop = self._lhs(n_samples=n_pop, n_dim=24) * 2.0 - 1.0
        pop = np.clip(pop, -1.0, 1.0)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(8, min(35, self.budget // n_pop))
        diversity_threshold = 0.08

        for gen in range(max_gen):
            if self.evals >= self.budget:
                break
            t_frac = 1.0 - gen / max_gen

            # Diversity monitoring & automatic rejuvenation
            pop_range = np.ptp(pop, axis=0)
            current_div = np.mean(pop_range)
            if current_div < diversity_threshold and gen > max_gen // 3:
                n_rej = n_pop // 2
                idxs = self.rng.choice(n_pop, n_rej, replace=False)
                pop[idxs] = self._lhs(n_samples=n_rej, n_dim=24) * 2.0 - 1.0
                pop = np.clip(pop, -1.0, 1.0)
                fitness[idxs] = np.array([self._evaluate(p, func) for p in pop[idxs]])

            valid_mask = np.isfinite(fitness)
            if not np.any(valid_mask):
                pop = self._lhs(n_samples=n_pop, n_dim=24) * 2.0 - 1.0
                pop = np.clip(pop, -1.0, 1.0)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                continue

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            # Gradient guidance recomputed periodically with variance scaling
            g_bias = np.zeros(24)
            grad_norm = 0.0
            if grad_func and is_best_valid and gen % 4 == 0:
                try:
                    full_best = np.concatenate([x_best[:18], x_best[18:]])
                    g = grad_func(full_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-10:
                            # Scale steps by population spread per dimension
                            dim_scale = np.maximum(np.ptp(pop, axis=0), 0.05)
                            step_magnitudes = 0.25 * dim_scale
                            g_bias[:18] = np.clip((g_clean / grad_norm) * step_magnitudes[:18], -0.25, 0.25)
                except Exception:
                    pass

            for i in range(n_pop):
                if self.evals >= self.budget:
                    break
                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                # Hybrid DE + Levy mutation
                levy_prob = 0.2 * t_frac + 0.05
                if self.rng.random() < levy_prob:
                    v = x_best + 0.7 * self._adaptive_levy(24)
                else:
                    F = 0.4 + 0.6 * t_frac
                    v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])

                v = np.clip(v, -1.0, 1.0)

                # Block-aware crossover
                cr = self.rng.random(24)
                cr[:18] = cr[:18] < (0.85 * t_frac + 0.15)
                cr[18:] = cr[18:] < (0.30 * t_frac + 0.10)
                trial = np.where(cr, v, pop[i])

                # Gradient perturbation
                if grad_norm > 1e-10 and self.rng.random() < 0.15:
                    trial[:18] += g_bias[:18] * 0.4

                trial = np.clip(trial, -1.0, 1.0)
                f_trial = self._evaluate(trial, func)

                # Intelligent cliff recovery
                if np.isinf(f_trial) and is_best_valid and grad_norm > 1e-10:
                    x_recovery = x_best.copy()
                    x_recovery[:18] = np.clip(x_best[:18] - g_bias[:18] * 2.0, -1.0, 1.0)
                    f_rec = self._evaluate(x_recovery, func)
                    if np.isfinite(f_rec):
                        trial, f_trial = x_recovery, f_rec
                    else:
                        trial = self._lhs(n_samples=1, n_dim=24)[0] * 2.0 - 1.0
                        trial = np.clip(trial, -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i], fitness[i] = trial, f_trial

        # Dynamic L-BFGS exploitation (only if convergence confirmed & budget remains)
        if self.evals < self.budget * 0.85 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                cats = x0[18:].copy()
                conts = x0[:18].copy()

                try:
                    full_x0 = np.concatenate([conts, cats])
                    g_init = grad_func(full_x0)
                    if g_init is None:
                        raise ValueError("Gradient missing")
                    g_init = np.nan_to_num(g_init, nan=0.0, posinf=0.0, neginf=0.0)
                except Exception:
                    return self.best_f, self.best_x

                def cost_wrap(x_c):
                    if self.evals >= self.budget:
                        return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), cats]), func)

                def grad_wrap(x_c):
                    full = np.concatenate([np.clip(x_c, -1.0, 1.0), cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                remaining = self.budget - self.evals
                max_iter = int(np.clip(remaining * 0.15, 10, 80))
                try:
                    res = minimize(cost_wrap, conts, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)] * 18,
                                   options={'maxiter': max_iter, 'ftol': 1e-12, 'gtol': 1e-10, 'maxls': 50})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats])
                except Exception:
                    pass

        return self.best_f, self.best_x
